insert into public.mushroom_growth_conditions (slug, best_after, soil_conditions, microhabitat, foraging_difficulty, foraging_tips, source, verified)
values
($g1$agaricus_augustus$g1$,$g1$Sommerpilz, Hauptzeit Juli-September (in Mitteleuropa Juni-Oktober). Schiebt oft schubartig nach längerer Trocken-/Hitzephase, wenn ergiebiger Regen einsetzt - dann erscheinen die Fruchtkörper innerhalb weniger Tage fast explosiv in grösserer Zahl.$g1$,null,$g1$Park- und Waldbewohner. Am häufigsten an Fichtenwald- und Forsträndern, lichte Stellen, Wegränder, Böschungen; gern bei Fichte und Eiche, seltener im Laubwald. Auch in Parks und Gärten.$g1$,$g1$mittel$g1$,null,$g1$Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)$g1$,true),
($g1$agaricus_campestris$g1$,$g1$Wärmeliebend; fruchtet ab Juli (Saison Mai-Oktober) vor allem in trocken-warmen Sommern nach ergiebigem Regen. Typisch erscheinen die Fruchtkörper ca. 7-10 Tage nach kräftigem Niederschlag, dann oft massenhaft in Gruppen, Reihen oder Hexenringen.$g1$,null,$g1$Offenes Grünland: Wiesen, Weiden (gern beweidet/gedüngt), Felder, Gärten und Parks. Kein Waldpilz - direkt im Gras, oft in Hexenringen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)$g1$,true),
($g1$albatrellus_confluens$g1$,$g1$Sommer bis Herbst, Hauptzeit etwa August-Oktober (Quellen nennen Juni-November). Fruchtet bodenständig nach feuchten Phasen im Nadelwald.$g1$,null,$g1$Nadelwald-Pilz, wächst am Boden (nicht am Holz) gesellig bei Nadelbäumen - je nach Quelle bei Fichte und/oder Kiefer; oft auf Lichtungen, an Waldwegen oder Bergwiesenrändern. Häufig in verschmelzenden Büscheln mit überlappenden Hüten.$g1$,$g1$experte$g1$,null,$g1$Recherche-Angabe geprüft via WebSearch (Mykorrhiza Fichte/Kiefer + Saison Jul-Okt bestätigt; unverändert übernommen)$g1$,true),
($g1$amanita_rubescens$g1$,$g1$Wenig wählerisch; Fruchtkörper von Juni bis Oktober (bei milder Witterung bis Dezember), einzeln bis gesellig. Erscheint zuverlässig nach feuchten Phasen über die ganze Pilzsaison verteilt - einer der ersten und am längsten erscheinenden Sommer-/Herbstpilze.$g1$,null,$g1$Mykorrhiza mit vielen Baumarten (Fichte, Tanne, Kiefer, Buche, Eiche). In Nadel-, Laub- und Mischwäldern, auch Parks und Gärten; oft an Waldwegen und lichten Stellen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)$g1$,true),
($g1$auricularia_auricula_judae$g1$,$g1$Ganzjährig, Hauptsaison November-März (frisch gut sammelbar August-April). Bildet Fruchtkörper immer dann, wenn ausreichend Feuchtigkeit da ist - besonders ergiebig nach längeren Regenphasen; gedeiht bei milden, feuchten Temperaturen und ist frostresistent.$g1$,null,$g1$Vor allem an geschwächtem oder totem Holunder, häufig auch an Buche; daneben Birke, Ulme, Ahorn u.a. Laubholz, sehr selten Nadelholz. An morschen Ästen, Stämmen und Totholz in feuchten Gebüschen, Auwäldern, Hecken.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)$g1$,true),
($g1$austernpilz$g1$,$g1$Spätherbst- bis Winterpilz; Hauptzeit etwa Mitte November bis Mitte Januar, frisch bis ins Frühjahr. Die heimische Form (Winterauster) fruchtet erst nach einem Kältereiz/Temperatursturz unter ~10°C ('Cold Shock'); wächst auch an frostfreien Wintertagen langsam weiter.$g1$,null,$g1$Büschelig an totem Laubholz - vor allem Buche, auch andere Laubbäume; selten Nadelholz. An Stümpfen, liegenden Stämmen und an Wunden/Verletzungen lebender Bäume, oft auch hoch oben am Stamm.$g1$,$g1$mittel$g1$,null,$g1$Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)$g1$,true),
($g1$boletus_aereus$g1$,$g1$Wärmeliebend - fruchtet nur in warmen Sommern; Saison etwa Juli-Oktober (manche Quellen ab Mai). Erscheint nach warmen Gewitterregen in der warmen Jahreszeit; profitiert vom Klimawandel und breitet sich nordwärts aus.$g1$,null,$g1$Mykorrhiza mit Laubbäumen, am häufigsten Eiche, auch Edelkastanie, Buche und Hagebuche. In warmen, lichten, älteren Eichen-, Buchen- oder Mischwäldern, an südexponierten Hängen und Waldrändern, auch in Parks.$g1$,$g1$experte$g1$,null,$g1$Recherche-Angabe geprüft via WebSearch (Eiche/Buche-Mykorrhiza + warmliebend Jul-Okt bestätigt; unverändert übernommen)$g1$,true),
($g1$boletus_reticulatus$g1$,$g1$Frühe Sommerart: Hauptschub Juni–Juli, in milden Lagen schon ab Mai bis in den Oktober. Fruchtet 1–2 Wochen nach ergiebigem Sommerregen bei warmem, schwülem Wetter (rund 15–20°C). Reagiert schneller auf Sommergewitter als der Herbst-Steinpilz.$g1$,null,$g1$Mykorrhiza-Partner sind Laubbäume: Eiche, Buche, Linde, auch Edelkastanie. Nur in Laub- und Laub-Nadel-Mischwäldern, nie im reinen Nadelwald. Gezielt an lichten, sonnigen Stellen suchen: Waldränder, Wegränder, grasige Lichtungen, Hangkanten in Eichen-/Buchenbeständen.$g1$,$g1$mittel$g1$,null,$g1$Faktencheck bestätigt (WebSearch: Wikipedia, Fungiversum, Pilzkurse Schweiz) — Saison Sommer + Laubbaum-Mykorrhiza korrekt, unverändert übernommen.$g1$,true),
($g1$butterpilz$g1$,$g1$Spätsommer bis Spätherbst, Hauptzeit August–November (in warmen Jahren ab Juni/Juli). Fruchtet schubweise rund 1–2 Wochen nach Regenphasen bei mild-feuchtem Wetter; einer der zuverlässigsten Pilze nach Herbstregen.$g1$,null,$g1$Mykorrhiza streng an Kiefer (Pinus) gebunden, v.a. junge Kiefern. In Nadel- und Mischwäldern, jungen Kiefernforsten, Aufforstungen. Gezielt an Wegrändern, Böschungen, Lichtungen und grasigen Schneisen mit jungen Kiefern suchen.$g1$,$g1$anfaenger$g1$,null,$g1$Faktencheck bestätigt (WebSearch: AWL.ch, Pilzkurse Schweiz, fungifriends) — Kiefer-Mykorrhiza exklusiv + Spätsommer/Herbst korrekt, unverändert übernommen.$g1$,true),
($g1$calocybe_gambosa$g1$,$g1$Frühjahrs-/Frühsommerart: April bis Juli, namensgebend rund um den St.-Georgs-Tag (23. April) bis Mai, oft in zwei Schüben (Ende April–Mitte Mai, dann Juni–Anfang Juli). Höhenabhängig — in den Bergen später. Fruchtet nach milder, feuchter Frühlingswitterung.$g1$,null,$g1$Sonnige, grasige Stellen an Waldrändern, Hecken (Prunetalia-Schlehenhecken), Haselgebüsch, Wiesen und in lichten Buchen-/Buchen-Tannenwäldern und Auwäldern. Oft entlang von Hecken- und Wegrändern. Wächst gesellig in Trupps, Bögen und breiten Hexenringen.$g1$,$g1$mittel$g1$,null,$g1$Faktencheck bestätigt (WebSearch: First-Nature, Pilzseite, Foraging Course Co.) — Frühjahrs-/Mai-Saison (NICHT Herbst) + Hecken/Wiesen-Habitat korrekt, unverändert übernommen.$g1$,true),
($g1$calvatia_gigantea$g1$,$g1$Spätsommer bis Herbst, Hauptzeit Juli–Oktober. Erscheint nach warmen, feuchten Phasen, oft einige Tage nach kräftigem Sommer-/Herbstregen. Schiesst dann schnell zu grossen Fruchtkörpern auf.$g1$,null,$g1$Kein Mykorrhiza-Partner — wächst auf offenen Flächen: Fett-/Viehweiden, gedüngte Wiesen, frisch gemähte Wiesen, Wegränder, Gärten, Parks, auch lichte Waldränder und Brennnessel-/Hochstaudenfluren. Standorttreu, oft jahrelang am selben Platz.$g1$,$g1$mittel$g1$,null,$g1$Faktencheck bestätigt (WebSearch: Wikipedia, Tintling, Fundkorb) — Saprobiont (kein Mykorrhiza) + Sommer–Herbst auf Weiden/Wiesen korrekt, unverändert übernommen.$g1$,true),
($g1$cantharellus_tubaeformis$g1$,$g1$Spätherbst-Spezialist: Hauptzeit Ende August/September bis in den Winter (November–Dezember, in milden Lagen bis Februar). Frosttolerant. Fruchtet nach den Herbstregen und hält die feuchte, kühle Spätsaison über lange durch.$g1$,null,$g1$In moosigen Nadel- und Mischwäldern, v.a. unter Fichte/Tanne; gerne in dicken Moospolstern, an feuchten Senken, Gräben, morschem Holz und entlang von Bachläufen. Wächst sehr gesellig, oft in dichten Teppichen, Reihen und Ringen.$g1$,$g1$anfaenger$g1$,null,$g1$Faktencheck bestätigt (WebSearch: AWL.ch, Wikipedia, 123pilzsuche) — Spätherbst/Winter bis Februar + moosige Nadelwälder korrekt, unverändert übernommen.$g1$,true),
($g1$champignon-de-paris$g1$,$g1$Als Wildform (Kulturflüchtling) Frühjahr bis Spätherbst, April–November, gehäuft nach sommerlichen/herbstlichen Regenfällen. Wild eher unregelmässig und nicht häufig; in Kultur ganzjährig auf Substrat. Wildvorkommen fruchten einige Tage nach warmem Regen.$g1$,null,$g1$Kein Mykorrhiza-Partner. Wild an/auf Kompost- und Misthaufen, in Gärten, an gedüngten Wiesen- und Waldrändern, in Gewächshäusern und Parks. Häufiger sind in der Schweiz die nahe verwandten Wiesen-Champignons auf Weiden und Wiesen.$g1$,$g1$mittel$g1$,null,$g1$Faktencheck plausibel — Saprobiont (kein Mykorrhiza) + Kompost/Garten-Habitat + Frühjahr–Spätherbst-Saison mykologisch konsistent, unverändert übernommen.$g1$,true),
($g1$clitocybe_nebularis$g1$,$g1$Spätherbstart: September bis November/Dezember, oft als einer der letzten reichlichen Pilze der Saison, bis nahe an die ersten Fröste. Fruchtet nach den Herbstregen bei kühler, feuchter Witterung.$g1$,null,$g1$In Laub- und Nadelwäldern sowie an Waldrändern, in der Falllaub-/Nadelstreu. Kein Mykorrhiza-Partner — Streuzersetzer. Wächst sehr gesellig, gerne in auffälligen, oft grossen Hexenringen und langen Reihen.$g1$,$g1$anfaenger$g1$,null,$g1$Faktencheck bestätigt (WebSearch: Pilzfinder, Wikipedia, Pilzmuseum) — Spätherbst-Saison + Streuzersetzer (kein Mykorrhiza) + Hexenringe in Laub-/Nadelwald korrekt, unverändert übernommen.$g1$,true),
($g1$eierschwamm$g1$,$g1$Juni bis Oktober (Hauptzeit Juli–September), in guten Jahren bis Spätherbst. Fruchtet, wenn Bodenfeuchte und Wärme zusammenfallen: 1–2 Wochen nach ergiebigem Regen bei milden 15–25°C. Nach trocken-heissem Frühsommer wirkt die erste Regenperiode oft schon nach 48–72 h.$g1$,$g1$Bevorzugt nährstoffarme, eher saure Böden; gedeiht in Fichten-, Buchen- und Mischwäldern auf solchen Standorten.$g1$,$g1$Mykorrhiza mit Fichte, Buche, Eiche, Kiefer und Tanne. In Fichten-, Buchen- und Mischwäldern; oft an moosigen Stellen, Waldrändern, Böschungen und lichten Partien. Wächst gesellig in Gruppen, selten einzeln.$g1$,$g1$anfaenger$g1$,$g1$Nach ergiebigem Regen 1–2 Wochen später an moosigen, lichten Stellen und Böschungen suchen; wächst gesellig in Gruppen, deshalb beim ersten Fund die Umgebung genau absuchen.$g1$,$g1$Mykologisch plausibel bestätigt (Cantharellus cibarius): Saison Juni–Oktober mit Schwerpunkt Juli–September, Mykorrhiza mit Fichte/Buche/Eiche/Kiefer/Tanne, nährstoffarme saure Böden. Quellen: Wikipedia (Echter Pfifferling), AWL.ch, fungiversum.de. Unverändert übernommen.$g1$,true),
($g1$flaemmling$g1$,$g1$August bis November, schwerpunktmässig im feuchten Herbst. Erscheint büschelig nach Regenperioden, wenn das Totholz gut durchnässt ist; mag feuchte, kühlere Witterung.$g1$,$g1$Nicht bodengebunden – Holzbewohner (Saprobiont). Substrat ist durchnässtes, morsches Laubholz; gedeiht besonders in feuchten Senken und Bach-/Auennähe.$g1$,$g1$An morschem, totem Laubholz, bevorzugt Rotbuche und Eiche (selten Nadelholz). Dicht gedrängt in vielhütigen Büscheln an Stubben, Stümpfen und am Boden liegenden Stämmen, oft in Bach-/Auennähe und feuchten Senken.$g1$,$g1$mittel$g1$,$g1$An Laubholz-Stümpfen und liegenden Stämmen in feuchten Senken suchen; die auffälligen vielhütigen Büschel sind gut erkennbar, treten aber nur nach durchnässtem Totholz auf.$g1$,$g1$Mykologisch plausibel bestätigt – die Angaben (büschelig, Laubholz Rotbuche/Eiche, Aug–Nov) beschreiben den Beringten Flämmling (Gymnopilus junonius), nicht den Geflecktblättrigen (G. penetrans, der auf Nadelholz wächst). Für G. junonius korrekt: dichte Büschel an totem Laubholz (Buche/Eiche), Saison August–Oktober/November. Quellen: fundkorb.de, digital-nature.de, tintling.com. Unverändert übernommen.$g1$,true),
($g1$flockenstieliger_hexenpilz$g1$,$g1$Einer der frühesten Röhrlinge: ab Mai (vereinzelt April) bis Oktober/November, gelegentlich bis Dezember. Schiebt nach warmen Regenphasen im Sommer und Herbst, oft in grösseren Gruppen bei feuchter Witterung.$g1$,$g1$Saure bis schwach saure Böden bevorzugt (gelegentlich auch auf kalkhaltigem Substrat). Typisch in sauren Nadel-, Misch- und Buchenwäldern.$g1$,$g1$Mykorrhiza vor allem mit Fichte, daneben Buche, Eiche, Tanne und andere Nadelbäume. In sauren Nadel-, Misch- und Buchenwäldern; gern an Wegrändern und lichten Stellen mit Heidelbeere/Moos.$g1$,$g1$anfaenger$g1$,$g1$Schon ab Mai an Wegrändern und lichten Stellen mit Heidelbeere/Moos in sauren Nadel- und Mischwäldern suchen; erscheint nach warmen Regenphasen oft in grösseren Gruppen.$g1$,$g1$Mykologisch plausibel bestätigt (Neoboletus erythropus): einer der frühesten Röhrlinge (ab Mai, vereinzelt April), Mykorrhiza mit Fichte/Buche/Eiche/Tanne, saure bis schwach saure Böden in Nadel-/Misch-/Buchenwäldern. Quellen: Wikipedia, fungiversum.de, AWL.ch. Unverändert übernommen.$g1$,true),
($g1$flockenstieliger-hexen-roehrling$g1$,$g1$Einer der frühesten Röhrlinge: ab Mai (vereinzelt April) bis Oktober/November, gelegentlich bis Dezember. Schiebt nach warmen Regenphasen im Sommer und Herbst, oft in grösseren Gruppen bei feuchter Witterung.$g1$,$g1$Saure bis schwach saure Böden bevorzugt (gelegentlich auch auf kalkhaltigem Substrat). Typisch in sauren Nadel-, Misch- und Buchenwäldern.$g1$,$g1$Mykorrhiza vor allem mit Fichte, daneben Buche, Eiche, Tanne und andere Nadelbäume. In sauren Nadel-, Misch- und Buchenwäldern; gern an Wegrändern und lichten Stellen mit Heidelbeere/Moos.$g1$,$g1$anfaenger$g1$,$g1$Schon ab Mai an Wegrändern und lichten Stellen mit Heidelbeere/Moos in sauren Nadel- und Mischwäldern suchen; erscheint nach warmen Regenphasen oft in grösseren Gruppen.$g1$,$g1$Mykologisch plausibel bestätigt (Neoboletus erythropus, identisch zu Slug flockenstieliger_hexenpilz): früher Röhrling ab Mai, Mykorrhiza mit Fichte/Buche/Eiche/Tanne, saure Böden. Quellen: Wikipedia, fungiversum.de, AWL.ch. Unverändert übernommen.$g1$,true),
($g1$hallimasch$g1$,$g1$Hauptsächlich Herbst: Juli/August bis November, je nach Witterung bis Dezember. Schiebt schubweise nach den ersten kühl-feuchten Herbstregen, oft massenhaft an einem Tag.$g1$,$g1$Nicht bodengebunden – Holzbewohner (Parasit/Saprobiont). Besiedelt Stämme, Stubben und (auch vergrabene) Wurzeln lebender wie toter Bäume; erscheint scheinbar aus dem Boden über Rhizomorphe.$g1$,$g1$Büschelig an Stämmen, Stubben, Wurzelstöcken und am Wurzelboden lebender wie toter Bäume; in Mitteleuropa vor allem an Laubholz. Auch in Parks, Grünanlagen und Gärten. Über Rhizomorphe oft scheinbar aus dem Boden, tatsächlich an vergrabenen Wurzeln.$g1$,$g1$anfaenger$g1$,$g1$Nach den ersten kühl-feuchten Herbstregen schubweise an Stämmen, Stubben und Wurzelstöcken suchen – auch in Parks und Gärten; erscheint oft massenhaft an einem Tag in dichten Büscheln.$g1$,$g1$Mykologisch plausibel (Armillaria spec.): Herbstpilz, büschelig an Holz/Stubben/Wurzeln lebender und toter Bäume, über Rhizomorphe scheinbar bodenständig, auch in Parks/Gärten. Allgemein gesichertes mykologisches Wissen. Unverändert übernommen.$g1$,true),
($g1$herbsttrompete$g1$,$g1$Spätsommer bis Herbst: ab Mitte August, Schwerpunkt September–Oktober (lokal bis November). Erscheint nach ergiebigen Niederschlägen im Spätsommer/Herbst; in guten Jahren als Massenpilz.$g1$,$g1$Kalkhaltige, eher nährstoffarme Böden; gedeiht in Laub- und Mischwäldern auf solchem Untergrund, oft an feuchten, schattigen Stellen.$g1$,$g1$Mykorrhiza vor allem mit Rotbuche (Fagus sylvatica), auch Eiche. In Laub- und Mischwäldern auf kalkhaltigem Untergrund; oft an feuchten, moosigen, schattigen Stellen, gern an Hängen und in Mulden, gesellig in dichten Trupps.$g1$,$g1$mittel$g1$,$g1$Nach ergiebigem Regen an feuchten, moosigen, schattigen Stellen unter Rotbuche auf Kalkboden suchen, gern an Hängen und in Mulden; die dunkle Färbung tarnt sie im Laub – langsam und genau am Boden absuchen, dann oft in dichten Trupps.$g1$,$g1$Mykologisch plausibel bestätigt (Craterellus cornucopioides): Mykorrhiza vor allem mit Rotbuche (auch Eiche) auf Kalkboden, Hauptsaison Spätsommer–Herbst (Aug–Nov), feuchte schattige Stellen, gesellig in Trupps. Schwer zu sehen wegen dunkler Tarnfärbung → 'mittel' plausibel. Quellen: Wikipedia (Totentrompete), AWL.ch, fundkorb.de. Unverändert übernommen.$g1$,true),
($g1$infundibulicybe_geotropa$g1$,$g1$Spätsommer bis Spätherbst: vereinzelt ab Juli, Hauptzeit September–November, manchmal bis in den frühen Winter. Schiebt nach den herbstlichen Regenfällen, oft viele Fruchtkörper gleichzeitig.$g1$,$g1$Bevorzugt feuchte, kalkhaltige Böden in Laub- und Mischwäldern sowie an Waldrändern und auf Wiesen.$g1$,$g1$Waldränder, lichter Misch- und Laubwald, Waldwiesen, Lichtungen, Parkanlagen und Wegränder. Wächst gern in auffälligen Hexenringen oder Reihen mit oft 50+ Fruchtkörpern; grosse, trichterförmige Hüte gut sichtbar.$g1$,$g1$mittel$g1$,$g1$An Waldrändern, auf Waldwiesen und in lichtem Laub-/Mischwald nach den auffälligen Hexenringen/Reihen Ausschau halten; die grossen, hellen Trichterhüte sind aus Distanz erkennbar – einen Ring gefunden, lohnt das Absuchen der ganzen Formation.$g1$,$g1$Mykologisch plausibel bestätigt (Infundibulicybe geotropa, Mönchskopf): Saison ab Juli, Schwerpunkt September–November; feuchte kalkhaltige Böden, Waldränder/lichter Wald/Wiesen; bildet grosse, weithin sichtbare Hexenringe; grosse trichterförmige Hüte. Quellen: Wikipedia (Mönchskopf), pilzkurse.com, digital-nature.de. Unverändert übernommen.$g1$,true),
($g1$kuehneromyces_mutabilis$g1$,$g1$Mehrere Schübe von Mai bis November, Hauptwellen im Frühjahr und Herbst. Fruchtet wenige Tage bis ~1 Woche nach feuchtem Wetter bei milden 10–18°C; nach kühlen, regnerischen Perioden besonders ergiebig. Anders als Mykorrhizapilze nicht streng saisonal — bei Feuchte ganzjährig in der wärmeren Hälfte möglich.$g1$,null,$g1$Büschelig auf und um morsche Laubholz-Stümpfe und liegendes Totholz, bevorzugt Buche, Birke, Weide, Erle, Linde; nur selten Nadelholz. Feuchte Laub- und Mischwälder, Bachränder, schattige morsche Stümpfe.$g1$,$g1$anfaenger$g1$,null,$g1$fact-checked: saprob auf Laubholz-Totholz, mehrere Schübe Frühjahr+Herbst, plausibel — unverändert$g1$,true),
($g1$lactarius_deliciosus$g1$,$g1$Hauptsaison Spätsommer bis Herbst, ca. August–Oktober (in milden Lagen bis November/erster Frost). Fruchtkörper 1–2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei milden Temperaturen; nach den ersten kühleren, feuchten Herbsttagen schiebt er zuverlässig.$g1$,null,$g1$Mykorrhiza streng mit Kiefer (v.a. Waldkiefer). In Kiefern-, Nadel- und Mischwäldern mit Kiefernbeteiligung; an lichten Stellen, Waldweg- und Waldrändern, oft in Gras/Moos unter jüngeren Kiefern. In CH typisch auf sandig-kalkigen Föhrenstandorten.$g1$,$g1$mittel$g1$,null,$g1$fact-checked: Kiefern-Mykorrhiza, Spätsommer/Herbst, plausibel — unverändert$g1$,true),
($g1$lactarius_deterrimus$g1$,$g1$August bis Oktober, Hauptschub September bis zum ersten harten Frost (oft November). Erscheint nach feuchtem Spätsommer-/Herbstwetter; die kühl-feuchten Herbsttage lösen den Hauptschub aus. Oft etwas früher und häufiger als der Edel-Reizker.$g1$,null,$g1$Mykorrhiza eng an Fichte gebunden. In Fichten- und fichtenreichen Nadel-/Mischwäldern; truppweise auf moosigem oder nadelbedecktem Boden, gern an Wegrändern, Lichtungen und unter jüngeren Fichten. In CH bis in höhere Lagen einer der häufigsten Reizker.$g1$,$g1$anfaenger$g1$,null,$g1$fact-checked: Fichten-Mykorrhiza, Herbst, plausibel — unverändert$g1$,true),
($g1$lactarius_volemus$g1$,$g1$Sommer bis Herbst, am häufigsten Juli–September, Spitzen an den wärmsten Augusttagen. Fruchtet bevorzugt bei sommerlicher Wärme einige Tage nach Regen — eher ein Wärmepilz als ein Spätherbstpilz.$g1$,null,$g1$Mykorrhiza mit Laub- und (seltener) Nadelbäumen, klar bevorzugt Buchen-/Laubwald, gern bei Eiche und Buche. Eher Hügel- und Bergland; im Flachland seltener. Lichte, ältere Laubwälder.$g1$,$g1$experte$g1$,null,$g1$fact-checked: Sommer/Herbst-Wärmepilz, Laubwald-bevorzugt, Hügel-/Bergland, plausibel (RL3-Art, hohe difficulty vertretbar) — unverändert$g1$,true),
($g1$laetiporus_sulphureus$g1$,$g1$Einjährige Fruchtkörper von (April/)Mai bis Oktober, Schwerpunkt spätes Frühjahr und Frühsommer. Erscheint nach warm-feuchten Phasen; junge, frische Konsolen bilden sich rasch bei Wärme und Luftfeuchte (Guttationstropfen bei feuchtem Wetter).$g1$,null,$g1$Bevorzugt Laubbäume: Eiche, Robinie, Weide, Pappel und Obstbäume (selten Nadelholz wie Lärche). Am Stamm, an Stammfuss, Starkästen, Schnitt-/Astwunden und Schnittflächen — oft in grösserer Höhe; dachziegelartig in Gruppen. Auch in Parks, Alleen, an Einzelbäumen.$g1$,$g1$anfaenger$g1$,null,$g1$fact-checked: Saison ab Mai mit Frühsommer-Schwerpunkt bestätigt, Laubholz-Wirte korrekt, anfaenger plausibel — unverändert$g1$,true),
($g1$leccinum_aurantiacum$g1$,$g1$Fruchtkörper von Juni bis Oktober (selten ab Mai). Erscheint nach ausreichenden Sommer-/Herbstniederschlägen bei mildem Wetter — typischer Sommer- bis Herbstpilz, oft schon im Hochsommer.$g1$,null,$g1$Mykorrhiza streng an Espe/Zitterpappel (Populus tremula) gebunden, generell bei Pappeln. Bei einzelnen Pappel-/Espengruppen, an Waldrändern, Lichtungen, in Mooren, gern an feuchteren, halblichten Stellen. Erscheint auch innerhalb von Nadel-/Mischwäldern — dort aber stets bei eingestreuten Espen/Pappeln, deren Wurzeln er besiedelt (nicht mit Fichte/Tanne vergesellschaftet).$g1$,$g1$mittel$g1$,null,$g1$korrigiert: L. aurantiacum s.str. ist Espen-/Pappel-Mykorrhiza, NICHT mit Fichte/Tanne vergesellschaftet. Ursprungstext 'auch in Fichten-Tannen-Wäldern mit eingestreuten Espen' war missverständlich (las wie Nadelholz-Partner) — präzisiert: der Pilz folgt nur den eingestreuten Espen/Pappeln. Saison Juni–Okt korrekt.$g1$,true),
($g1$leccinum_pseudoscabrum$g1$,$g1$Fruchtkörper von Juni bis Oktober. Erscheint nach Sommer-/Herbstregen bei mildem Wetter; einer der frühen Röhrlinge, oft schon ab Frühsommer bei ausreichender Feuchte.$g1$,null,$g1$Mykorrhiza mit der Hainbuche (Carpinus betulus). In hainbuchenreichen Laub- und Mischwäldern, an Waldrändern, Strassenrändern, in Parkanlagen und Alleen — immer in unmittelbarer Nähe von Hainbuchen.$g1$,$g1$mittel$g1$,null,$g1$fact-checked: Hainbuchen-Mykorrhiza korrekt, Juni–Okt, mittel plausibel — unverändert$g1$,true),
($g1$leccinum_versipelle$g1$,$g1$Frühstarter ab Juni (in milden Jahren schon Mai) bis Oktober; Hauptschub August–Oktober. Bei feucht-mildem Sommerklima 1–2 Wochen nach ergiebigem Regen oft kurzzeitiges Massenvorkommen.$g1$,$g1$Bevorzugt eher saure, durchlässige Böden; gedeiht auf sandig-humosen bis moorigen Standorten in Birkennähe.$g1$,$g1$Strikte Mykorrhiza mit Birke (Betula pendula/pubescens). Suche gezielt bei einzelstehenden oder lichten Birken, Birken-Waldränder, Heide- und Moorrandlagen, bemooste lichte Stellen.$g1$,$g1$mittel$g1$,$g1$Erst die Wirtsbaumart suchen, nicht den Pilz: lichte Birken, Birken-Waldränder und Moorränder absuchen. 1–2 Wochen nach ergiebigem Regen erscheint er bei Birken oft truppweise.$g1$,$g1$Mykologisch plausibel und per WebSearch bestätigt (de.wikipedia.org Birken-Rotkappe / Vielverfärbender Birkenpilz, pilzlexikon.eu): obligate Birken-Mykorrhiza, Frühstarter ab Mai/Juni, Hauptsaison August–Oktober. Keine Korrektur nötig.$g1$,true),
($g1$lepista_nuda$g1$,$g1$Spätherbst-Pilz: September bis in den Spätfrost hinein, Hauptsaison Oktober–November. Erscheint zuverlässig nach den ersten kühlen, feuchten Herbsttagen; verträgt leichte Fröste.$g1$,$g1$Folgezersetzer auf nährstoffreicher, humoser Laub- und Nadelstreu; gedeiht in dicker Falllaubschicht und auf Kompost.$g1$,$g1$Saprophyt (Folgezersetzer, keine Mykorrhiza). Laub- und Laubmischwälder, auch Nadelwald, Auwald, Hecken, Gärten und Komposthaufen. Wächst gehäuft in Hexenringen und Reihen in der Laubstreu.$g1$,$g1$anfaenger$g1$,$g1$Einer der letzten Herbstpilze – erst suchen, wenn die ersten Nachtfröste durch sind. Dicke Laubstreu, Heckenränder und Komposthaufen abgehen; auf Hexenringe und Reihen in der violetten Streu achten.$g1$,$g1$Mykologisch plausibel und per WebSearch bestätigt (de.wikipedia.org Violetter Rötelritterling, fundkorb.de, digital-nature.de): Saprophyt/Folgezersetzer, ausgeprägter Spätherbstpilz Oktober–November mit leichter Frosttoleranz. Keine Korrektur nötig.$g1$,true),
($g1$lycoperdon_perlatum$g1$,$g1$Lange Saison Juli (vereinzelt Juni) bis November; Schwerpunkt Spätsommer/Herbst. Erscheint einige Tage nach Regen, witterungsabhängig in grosser Zahl.$g1$,$g1$Bodensaprophyt auf humoser Streu und Waldböden; anspruchslos, auf magerem Weide- und Brachboden ebenso wie im Wald.$g1$,$g1$Saprophyt am Boden, häufig truppweise. Am häufigsten in Nadel- und Nadelmischwäldern, auch reine Laubwälder; zudem Waldränder, Weiden, trockene Wiesen und Brachen, im Gebirge.$g1$,$g1$anfaenger$g1$,$g1$Truppweise an Waldwegrändern und auf bemoosten Waldböden; einige Tage nach Regen erscheinen ganze Gruppen. Junge, innen rein weisse Exemplare beachten.$g1$,$g1$Mykologisch plausibel (Standard-Lexikonwissen): häufiger Bodensaprophyt, lange Saison Juli–November mit Herbstschwerpunkt, Nadel-/Mischwald-Schwerpunkt. Keine Korrektur nötig.$g1$,true),
($g1$marasmius_oreades$g1$,$g1$Mai bis November, mehrere Schübe pro Jahr. Erscheint sehr zuverlässig direkt nach ergiebigem Regen, oft in Massen; bei feucht-warmer Witterung wiederholt.$g1$,$g1$Grasland-Saprophyt; gedeiht auf nährstoffarmen bis mittleren Wiesen- und Rasenböden, auch auf Magerwiesen.$g1$,$g1$Saprophyt im Gras. Wiesen, Weiden, Magerwiesen, Parks, Rasen in Gärten und grasige Wegränder, auch grasige Waldstellen. Wächst typisch in Hexenringen/Reihen — das Gras im Ring ist oft auffällig sattgrün.$g1$,$g1$anfaenger$g1$,$g1$Auf Hexenringe in der Wiese achten – das Gras im Ring leuchtet oft auffällig sattgrün. Reagiert sehr schnell auf Regen, daher 1–3 Tage nach einem Schauer die gleichen Wiesen erneut absuchen.$g1$,$g1$Mykologisch plausibel und per WebSearch bestätigt (de.wikipedia.org Nelken-Schwindling, pilzfinder.de, naturdetektive.at): Grasland-Saprophyt, Saison Mai–November in mehreren Schüben, charakteristische Hexenringe mit sattgrünem Gras. Keine Korrektur nötig.$g1$,true),
($g1$marone$g1$,$g1$Je nach Witterung Juni–November, Hauptschub September bis erste Novemberhälfte. Etwa 5–10 Tage nach kräftigem Regen; reagiert wie der Steinpilz rasch auf feucht-milde Bedingungen, in trockenen Lagen nur bei ausreichend Regen.$g1$,$g1$Bevorzugt bodensaure, eher magere Nadel- und Mischwaldböden; typisch in älteren Fichtenwäldern auf saurer Nadelstreu.$g1$,$g1$Mykorrhiza bevorzugt mit Fichte und Lärche, auch Buche, Eiche, Esskastanie. Charakterart bodensaurer Nadel- und Mischwälder; vor allem ältere Fichtenwälder, oft truppweise/in Massen.$g1$,$g1$anfaenger$g1$,$g1$Ältere, bodensaure Fichtenwälder gezielt absuchen; erscheint oft truppweise. Etwa 5–10 Tage nach kräftigem Regen losziehen; reagiert ähnlich rasch wie der Steinpilz auf feucht-milde Witterung.$g1$,$g1$Mykologisch plausibel und per WebSearch bestätigt (awl.ch, fungiversum.de, pilzbuch-pilzwelten.de): Mykorrhiza bevorzugt mit Fichte/Lärche (auch Buche/Eiche/Esskastanie), Hauptsaison Mitte September–November, vor allem ältere Fichtenwälder. Keine Korrektur nötig.$g1$,true),
($g1$maronenroehrling$g1$,$g1$Je nach Witterung Juni–November, Hauptschub September bis erste Novemberhälfte. Etwa 5–10 Tage nach kräftigem Regen; reagiert wie der Steinpilz rasch auf feucht-milde Bedingungen, in trockenen Lagen nur bei ausreichend Regen. (Boletus badius = Imleria badia, identisch mit Marone.)$g1$,$g1$Bevorzugt bodensaure, eher magere Nadel- und Mischwaldböden; typisch in älteren Fichtenwäldern auf saurer Nadelstreu.$g1$,$g1$Mykorrhiza bevorzugt mit Fichte und Lärche, auch Buche, Eiche, Esskastanie. Charakterart bodensaurer Nadel- und Mischwälder; vor allem ältere Fichtenwälder, oft truppweise/in Massen.$g1$,$g1$anfaenger$g1$,$g1$Ältere, bodensaure Fichtenwälder gezielt absuchen; erscheint oft truppweise. Etwa 5–10 Tage nach kräftigem Regen losziehen; reagiert ähnlich rasch wie der Steinpilz auf feucht-milde Witterung.$g1$,$g1$Mykologisch plausibel und per WebSearch bestätigt (awl.ch, fungiversum.de): identisch mit Marone (Imleria badia, syn. Boletus/Xerocomus badius). Fichten-/Lärchen-Mykorrhiza, Hauptsaison Mitte September–November. Keine Korrektur nötig.$g1$,true),
($g1$morchelchampignon$g1$,$g1$Frühjahrspilz März–Mai (Mittelland früh, Gebirge bis zur Baumgrenze später). Schiebt, wenn die nächtliche Bodentemperatur stabil bei ~10–12°C liegt; ca. 3–4 Tage nach kräftigem Frühjahrsregen plus einigen milden, sonnigen Tagen.$g1$,$g1$Bevorzugt kalkhaltige, nährstoffreiche, humose und eher feuchte, aber gut durchlüftete Böden; typisch auf Auenböden und Schwemmland an Flussufern.$g1$,$g1$Saprophyt. Lichte Auen- und Laubwälder, gerne bei Esche, Ulme und Pappel; Flussufer-Lagen (in der CH z.B. Aare, Reuss, Emme, Limmat). Zeigerpflanzen: Esche, Bärlauch, Schlüsselblume, Buschwindröschen, Pestwurz.$g1$,$g1$experte$g1$,$g1$Frühjahrs-Auenwälder an Flussufern (Aare, Reuss, Emme, Limmat) auf kalkhaltigem Boden absuchen. An Zeigerpflanzen orientieren: Esche, Bärlauch, Schlüsselblume, Buschwindröschen, Pestwurz. Losziehen, wenn nach Frühjahrsregen einige milde, sonnige Tage folgen.$g1$,$g1$Mykologisch plausibel und per WebSearch bestätigt (pilzkurse.com, awl.ch Speisemorchel, myk.univie.ac.at): Frühjahrspilz März–Mai (NICHT Herbst), Saprophyt in Auen-/Laubwäldern bei Esche/Ulme/Pappel auf kalkhaltigem Boden. Saison korrekt als Frühjahr angegeben. Keine Korrektur nötig.$g1$,true),
($g1$morchella_elata$g1$,$g1$Frühjahr März–Mai (in höheren Lagen bis Juni), kurz nach der Schneeschmelze an den ersten warmen, milden Tagen. Schub kommt nach feucht-mildem Wetter, wenn der Boden sich erwärmt; oft 1–2 Wochen nach gründlicher Durchfeuchtung. Erscheint früher als die Speisemorchel.$g1$,null,$g1$Saprobiont (kein Mykorrhiza-Pilz). Auwälder, Laub-/Mischwälder, Waldränder, Böschungen, Gebüsch in Parks. Gerne unter Esche, Pappel, Ulme, Eiche, Hainbuche, Birke, Weide. Auch auf Holzlagerplätzen, Brandstellen, Kahlschlägen und gemulchten Flächen in Gärten/Siedlungen.$g1$,$g1$experte$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$parasol$g1$,$g1$Hauptsaison Juli–November, Schwerpunkt Spätsommer/Herbst. Schübe folgen einige Tage bis ~1–2 Wochen nach ergiebigem Regen bei noch warmem Wetter. In trockenen Sommern erst ab dem ersten kräftigen Spätsommer-/Herbstregen.$g1$,null,$g1$Saprobiont. Lichte Buchen-, Eichen- und Mischwälder mittleren Alters, sehr oft an Waldrändern, auf Lichtungen und Waldwegen; auch Magerwiesen, Weiden, Parks und Gärten. Steht meist gut sichtbar einzeln oder in Hexenringen an offenen, sonnigen Lagen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$roetling$g1$,$g1$Sommer bis Spätherbst, etwa Juni–Oktober/November (vereinzelt ab Mai), Schwerpunkt im warmen Sommer und am Übergang Oktober/November. Erscheint einige Tage nach Regen auf warmen, gedüngten Flächen.$g1$,null,$g1$Saprobiont auf offenen Flächen. Gedüngte, oft beweidete Wiesen und Weiden — besonders Schaf-, Pferde- und Rinderweiden, Feldränder, Nähe von Ställen und Komposthaufen; gelegentlich unter Nadelbäumen (Fichte/Wacholder). Häufig in Hexenringen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$rotfuss_hexen_roehrling$g1$,$g1$Einer der frühen Röhrlinge: ab Mai bis in den Spätherbst, in mehreren Schüben. Fruchtet nach warmem, feuchtem Wetter; Schübe folgen üblicherweise einige Tage bis ~1–2 Wochen nach ergiebigem Regen bei sommerlichen Temperaturen.$g1$,null,$g1$Mykorrhiza mit Laub- und Nadelbäumen, besonders Buche, Eiche und Fichte. Laub-, Nadel- und Mischwälder; oft im Moos und an etwas saureren, bodensauren Stellen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$rotkappe_birken$g1$,$g1$Sommer bis Herbst, Hauptsaison Juli–Oktober (potenziell Juni–November). Schübe folgen einige Tage bis rund 1–2 Wochen nach ergiebigem Regen bei mildem Wetter; nach feuchten Spätsommer-/Herbstphasen besonders reichlich.$g1$,null,$g1$Mykorrhiza ausschließlich mit Birken (Betula). Birken in parkartigen Flächen, an Wald- und Wegrändern, in Nadelmischwäldern mit eingestreuten Birken, Moor-/Heidesäumen; in reinen Birkenwäldern eher seltener.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$russula_cyanoxantha$g1$,$g1$Frühsommer bis Spätherbst, Hauptfruktifikation Juli–Oktober (in manchen Jahren schon Mai/Juni, vereinzelt bis Anfang November). Erscheint einige Tage bis ~1–2 Wochen nach durchdringendem Regen bei warmem Wetter.$g1$,null,$g1$Mykorrhiza vor allem mit Rotbuche, auch Eiche, seltener Fichte/Weißtanne. Laub- und Mischwälder, besonders Buchen- und Buchen-Tannen-Mischwälder (Waldmeister-Buchenwald). Wegen geringer Ansprüche in sehr vielen Waldtypen anzutreffen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$russula_vesca$g1$,$g1$Frühsommer bis Herbst, ab Juni; Hauptsaison Juli–September, noch bis Oktober. Schübe folgen einige Tage bis ~1–2 Wochen nach ergiebigem, warmem Regen.$g1$,null,$g1$Mykorrhiza mit Laub- und Nadelbäumen, besonders Rotbuche, Eiche, Fichte und Kiefer. Laub-, Nadel- und Mischwälder sowie Heiden; oft auf sandigem Boden unter Eichen und Buchen.$g1$,$g1$anfaenger$g1$,null,$g1$Recherche + Faktencheck (mykologische Quellen)$g1$,true),
($g1$russula_virescens$g1$,$g1$Sommer bis Herbst, Juni–Oktober; erscheint einige Tage nach warmen Sommerregen, besonders reichlich in warmen, schwülen Sommern bei milden 15–22 °C. Hauptschub Juli–September.$g1$,$g1$Bevorzugt eher nährstoffarme, oft leicht saure bis neutrale Böden in warmen Laubwäldern; verträgt auch wärmebegünstigte, trockenere Standorte.$g1$,$g1$Mykorrhiza-Partner v. a. Eiche, Buche und Hainbuche (selten Nadelbäume); in warmen Laub- und Laubmischwäldern, gern an lichten, sonnigen Stellen wie Waldrändern, Wegböschungen und Lichtungen.$g1$,$g1$mittel$g1$,$g1$Auf das typisch spangrüne, feldrig-aufgerissene (kacheliges Muster) Hutoberhäutchen achten — bestes Merkmal. In wärmebegünstigten Eichen-/Buchenwäldern an lichten Stellen suchen, 2–5 Tage nach warmem Sommerregen. Erscheint einzeln bis in kleinen Gruppen, kehrt jährlich an dieselben warmen Hangstandorte zurück.$g1$,$g1$AWL.ch / Pilzverein Region Baden (pilz-baden.ch) / 123pilzsuche.de / Fundkorb.de — Mykorrhiza Eiche/Buche/Hainbuche, Saison Sommer–Herbst bestätigt$g1$,true),
($g1$sarcodon_imbricatus$g1$,$g1$Spätsommer bis Herbst, etwa August–November; fruchtet nach herbstlicher Feuchte und ersten kühleren, regnerischen Phasen. Schübe oft mehrere Jahre am selben Standort.$g1$,$g1$Saure, eher nährstoffarme Nadelwaldböden; bevorzugt moosige, podsolige Standorte der Hügel- bis Bergstufe.$g1$,$g1$Mykorrhiza-Partner vor allem Fichte (Picea), auch Tanne/Kiefer; in moosreichen Nadelwäldern der Hügel- und Bergstufe, gern in Fichtenforsten und an moosigen, sauren Stellen.$g1$,$g1$mittel$g1$,$g1$In älteren, moosreichen Fichtenwäldern der mittleren bis höheren Lagen suchen, oft truppweise. Markante grobe, dunkle Hutschuppen und Stacheln (statt Lamellen) auf der Hutunterseite sind unverwechselbar. Standorte merken — der Pilz kehrt jahrelang an dieselbe Stelle zurück. Hauptzeit nach den ersten kühl-feuchten Herbsttagen.$g1$,$g1$Fundkorb.de / AWL.ch / lexikon-pilze.de / pilzkurse.com (Schweiz) — Mykorrhiza Fichte, Saison Spätsommer–Herbst (Aug–Nov) bestätigt$g1$,true),
($g1$schopftintling$g1$,$g1$Nach Regen von Mai bis Oktober/November; zwei Schübe — Frühjahr (April–Juni) und stärker im Herbst (September–November). Erscheint sehr schnell, oft schon 1–2 Tage nach durchdringendem Regen.$g1$,$g1$Nährstoffreiche, stickstoffhaltige, oft gestörte oder gedüngte Böden; verträgt verdichtete Erde an Wegrändern, Schuttplätzen und Baustellen.$g1$,$g1$Saprobiont (kein Mykorrhiza-Partner) auf gedüngten Wiesen, Weiden, Rasen, Parks, Gärten, Wegrändern, Parkplätzen, Straßen- und Waldrändern; typischer Siedlungs-/Kulturlandschaftspilz.$g1$,$g1$anfaenger$g1$,$g1$Direkt nach kräftigem Regen suchen — die jungen, noch geschlossenen, weiß-zylindrischen Fruchtkörper erscheinen explosiv über Nacht. Oft in Gruppen oder Hexenringen auf Rasenflächen und Wegrändern. Sehr kurzlebig: zerfließt rasch zu schwarzer Tinte (Autolyse), daher nur ganz junge Exemplare sind brauchbar. Leicht erkennbar durch schopfig-schuppigen Hut.$g1$,$g1$Allgemein etabliertes mykologisches Wissen (Coprinus comatus): Saprobiont, Siedlungs-/Wiesenpilz, Doppel-Schub Frühjahr+Herbst — plausibel, keine Korrektur nötig$g1$,true),
($g1$semmelstoppelpilz$g1$,$g1$Spätsommer bis Herbst, August–November (regional bis in den Frühwinter); fruchtet nach feuchter Spätsommer-/Herbstwitterung. Bildet oft Hexenringe und kehrt jährlich an dieselben Stellen zurück.$g1$,$g1$Bevorzugt etwas kalkhaltige, basenreiche Böden; gedeiht aber auch auf neutralen bis schwach sauren, moosigen Waldböden in Laub- und Nadelwäldern.$g1$,$g1$Mykorrhiza-Partner Buche, Eiche, Fichte und Tanne; in Laub-, Nadel- und Mischwäldern, gern in moosigen Bereichen und an Wegböschungen.$g1$,$g1$anfaenger$g1$,$g1$Im moosigen Unterwuchs von Laub- und Nadelwäldern suchen, oft truppweise oder in Hexenringen. Die weichen, brüchigen Stacheln (statt Lamellen) auf der Hutunterseite sind das sichere, anfängerfreundliche Merkmal — kaum verwechselbar. Standorte merken, da er jährlich wiederkehrt.$g1$,$g1$Wikipedia / AWL.ch / Fundkorb.de — Mykorrhiza Buche/Fichte/Tanne, kalkhold, Saison Spätsommer–Herbst (Aug–Nov) bestätigt$g1$,true),
($g1$shiitake$g1$,$g1$In Mitteleuropa praktisch nur kultiviert; kein natürliches Freilandvorkommen. Auf beimpftem Laubholz fruchtet er stammabhängig im Frühjahr oder Herbst bei feucht-mildem Wetter (Fruchtung ~10–20 °C), oft nach Temperatur-/Feuchtereiz.$g1$,$g1$Kein Bodenpilz (lignikol/holzbewohnend); benötigt feuchtgehaltenes, totes Hartholz als Substrat statt Erdboden.$g1$,$g1$Wächst auf totem Laubholz, vor allem Eiche, Buche, Edelkastanie (im Ursprung der Shii-Baum/Pasania); in Mitteleuropa auf beimpften Hartholzstämmen oder -dübeln. Wildvorkommen nur in Ostasien.$g1$,$g1$experte$g1$,$g1$Kein klassischer Wildsammel-Pilz in der Schweiz — Freilandvorkommen fehlt. In der Praxis nur über eigene Beimpfung von Hartholzstämmen (Eiche/Buche) mit Brut zu ernten. Stämme schattig und feucht lagern, Fruchtung durch Wässern/Kältereiz auslösen. 'experte' wegen Kultivierungsaufwand statt Bestimmung.$g1$,$g1$Allgemein etabliertes mykologisches Wissen (Lentinula edodes): lignikol auf Eiche/Buche/Edelkastanie, in Mitteleuropa nur kultiviert, Wildvorkommen Ostasien — plausibel, keine Korrektur nötig$g1$,true),
($g1$sparassis_crispa$g1$,$g1$Spätsommer bis Herbst, etwa August–November (regional ab Juli, bis Dezember); fruchtet nach feuchter Spätsommerwitterung. Kommt jahrelang am selben Baum wieder.$g1$,$g1$Kein eigentlicher Bodenpilz — parasitisch/saprob an Kiefern-Wurzelholz; wächst an der Stammbasis lebender oder absterbender Kiefern sowie auf Stümpfen, gern auf sauren Sandböden der Kiefernforste.$g1$,$g1$Fast ausschließlich an der Stammbasis und über den Wurzeln von Kiefern (selten Fichte/Lärche), auch an Stümpfen und am Boden in unmittelbarer Baumnähe; in Kiefernwäldern und -forsten.$g1$,$g1$mittel$g1$,$g1$Gezielt an der Stammbasis und über den Wurzeln älterer Kiefern absuchen — der blumenkohl-/badeschwammartige, ocker-gelbliche Fruchtkörper ist unverwechselbar. Erscheint meist einzeln, aber groß; ein produktiver Baum trägt über Jahre. 'mittel', weil das Auffinden Standortkenntnis (alte Kiefern) erfordert, die Bestimmung selbst aber einfach ist.$g1$,$g1$Wikipedia / Fundkorb.de / tintling.com / fungiversum.de — Wirtsbaum Kiefer, Stammbasis-parasit, Saison Aug–Nov bestätigt$g1$,true),
($g1$steinpilz$g1$,$g1$Frühsommer bis Spätherbst; Hauptzeit Ende August–Oktober. Am besten ca. 5–10 (1–2 Wochen) Tage nach ergiebigem Regen bei mildem Wetter 15–23 °C und nicht zu kalten Nächten; erscheint in Schüben.$g1$,$g1$Anpassungsfähig auf sauren bis neutralen, eher nährstoffarmen Wald- und Bergböden; gedeiht auf moosigen, durchlässigen Standorten, oft bei Heidelbeer-Unterwuchs.$g1$,$g1$Mykorrhiza-Partner v. a. Fichte und Buche (auch Kiefer, Tanne, Eiche, Birke); im Bergland mit Fichte, im Flachland mit Buche/Eiche. Sonnige Waldränder, Wegränder und Lichtungen; Moospolster und Heidelbeeren sind gute Zeigerpflanzen.$g1$,$g1$mittel$g1$,$g1$5–10 Tage nach ergiebigem warmem Regen suchen, wenn die Nächte noch nicht zu kalt sind. Sonnige Waldränder, Wegböschungen und Lichtungen mit Fichte/Buche absuchen; Moospolster und Heidelbeerkraut sind verlässliche Zeigerpflanzen. Erscheint schubweise — wo einer steht, sind oft mehrere. Der feste, weiße, nicht blauende Schwamm und das helle Stielnetz sind sichere Merkmale.$g1$,$g1$Allgemein etabliertes mykologisches Wissen (Boletus edulis): Mykorrhiza Fichte/Buche/Kiefer/Eiche, Sommer–Spätherbst, ~1–2 Wochen nach Regen — plausibel, keine Korrektur nötig$g1$,true),
($g1$suillus_granulatus$g1$,$g1$Hauptzeit Juli bis Oktober, einzelne Trupps schon ab Juni. Fruchtet schubweise rund 1 Woche nach ergiebigem Regen bei mildem Wetter (ca. 12-18°C); profitiert von feuchtwarmen Spätsommer-Perioden und kommt oft truppweise in mehreren Schüben.$g1$,$g1$Bevorzugt kalkhaltige bis neutrale Böden; gedeiht gut auf basenreichen, eher trockenen bis frischen Standorten. Anders als viele Schmierröhrlinge nicht an saure Böden gebunden.$g1$,$g1$Mykorrhiza mit zweinadeligen Kiefern (Föhre/Pinus). In CH unter Kiefern an Waldrändern, Lichtungen, Wegrändern, in lichten Föhrenwäldern, Parkanlagen und auf Weiden mit Kiefernbestand. Sonnige, warme Stellen bevorzugt.$g1$,$g1$anfaenger$g1$,$g1$An warmen, sonnigen Kiefern-Standorten gezielt suchen - Wegränder, Lichtungen und lichte Föhrenbestände nach Regen absuchen. Erscheint truppweise, oft in lockeren Gruppen; nach dem ersten Fund die Umgebung im Umkreis absuchen. Tritt schubweise rund eine Woche nach ergiebigem Regen auf.$g1$,$g1$Web-Recherche Juni 2026: fungiversum.de, fundkorb.de, pilzmuseum.at, pilz-baden.ch (CH), Wikipedia - Mykorrhiza zweinadelige Kiefer, Juli-Oktober, kalkhaltige Böden bestätigt.$g1$,true),
($g1$suillus_grevillei$g1$,$g1$Juni bis November, Sammelschwerpunkt Juli bis Oktober (witterungsabhängig). Erscheint zuverlässig einige Tage nach Niederschlag bei milden Temperaturen; einer der ersten Röhrlinge im Jahr und oft bis in den Spätherbst.$g1$,$g1$Keine besonderen Bodenansprüche; auf unterschiedlichen Substraten zu finden, solange die Lärche als Partner vorhanden ist. Wächst auf sauren bis kalkhaltigen, frischen Böden.$g1$,$g1$Obligater Mykorrhiza-Partner der Lärche (Larix), nahezu immer nur dort. In CH unter Europäischer Lärche - Lärchenwälder, lärchenhaltige Mischwälder, Alleen, Parkanlagen, junge Aufforstungen, Waldränder. Selten unter anderen Lärchen/Douglasie.$g1$,$g1$anfaenger$g1$,$g1$Strikt an Lärchen gebunden - erst die Lärche finden, dann den Pilz: lohnt sich, gezielt Lärchenbestände, Alleen und junge Aufforstungen abzusuchen. Da einer der frühesten Röhrlinge, schon ab Frühsommer kontrollieren. Erscheint einige Tage nach Regen, oft truppweise unter dem Baum.$g1$,$g1$Web-Recherche Juni 2026: Wikipedia (Gold-Röhrling), fundkorb.de, pilzmuseum.at, tintling.com - obligater Lärchen-Partner, Juni-November, erster Röhrling des Jahres bestätigt.$g1$,true),
($g1$suillus_variegatus$g1$,$g1$Juli bis November, besonders häufig im Herbst (September-Oktober). Fruchtet nach feuchten Herbstperioden; reagiert auf Regen mit mildem Wetter, oft etwas später in der Saison als andere Schmierröhrlinge.$g1$,$g1$Bevorzugt magere, saure und sandige Böden. Typisch für nährstoffarme Standorte; auf basenarmen, sauren Sandböden nicht selten.$g1$,$g1$Mykorrhiza mit zweinadeligen Kiefern (Föhre/Pinus). In CH in Kiefern-/Föhrenwäldern auf sauren Sandböden, Moorrandwäldern, Heideflächen mit Kiefern. Bevorzugt magere, saure Nadelwald-Standorte.$g1$,$g1$anfaenger$g1$,$g1$Saure, sandige Kiefernstandorte und Heideflächen mit Föhren bevorzugt absuchen - oft an magereren Stellen als andere Schmierröhrlinge. Etwas später in der Saison erscheinend; nach feuchten Herbstperioden (September-Oktober) am ergiebigsten. Truppweise zwischen Moos und Heidekraut suchen.$g1$,$g1$Web-Recherche Juni 2026: fundkorb.de, fungiversum.de, LWF-Wissen 57 (Pilze an der Kiefer), pilzbestimmer.de - Kiefer-Mykorrhiza, saure Sandböden, Juli-November mit Herbstschwerpunkt bestätigt.$g1$,true),
($g1$xerocomus_subtomentosus$g1$,$g1$Juli bis Oktober (gelegentlich ab Frühsommer, selten Frühjahr). Erscheint einige Tage nach Regen bei feuchtwarmer Witterung; über die ganze warme Jahreszeit verstreut, mit Schwerpunkt Spätsommer/Herbst.$g1$,$g1$Wenig wählerisch; auf sauren bis neutralen, frischen Böden. Häufig in krautreichen, eher bodensauren Wäldern, aber breites Standortspektrum.$g1$,$g1$Mykorrhiza mit Laub- und Nadelbäumen (breites Spektrum). In CH in fast allen Laub- und Mischwäldern, auch Nadelwald, Gärten und Parks. Oft an moosigen, grasigen Stellen, Waldwegrändern und Lichtungen.$g1$,$g1$anfaenger$g1$,$g1$Weit verbreitet und wenig standort-wählerisch - in nahezu allen Wäldern möglich. Gezielt an moosigen, grasigen Stellen, Waldwegrändern und Lichtungen suchen. Erscheint einzeln bis verstreut über die ganze warme Jahreszeit, Schwerpunkt Spätsommer/Herbst nach Regen.$g1$,$g1$Web-Recherche Juni 2026: Wikipedia (Ziegenlippe), fundkorb.de, digital-nature.de, pilz-sammler.de - breites Mykorrhiza-Spektrum Laub- und Nadelbäume, Juli-Oktober bestätigt.$g1$,true),
($g1$zigeunerpilz$g1$,$g1$Hauptsaison August bis Oktober (von Spätsommer bis Herbst). Fruchtet nach ergiebigen Herbstregen bei kühler werdender Witterung; zeigt erratisches Jahresverhalten - manche Jahre kaum, dann plötzlich Massenvorkommen.$g1$,$g1$Saure, nährstoffarme und sandige Böden. Typisch für basenarme, magere Standorte sowie Moorrandbereiche; meidet kalkreiche Böden.$g1$,$g1$Mykorrhiza vor allem mit Fichte und Kiefer (selten Buche). In CH in nährstoffarmen sauren Nadelwäldern, gern bei Heidelbeeren (Vaccinium), in Mooren und Bergnadelwäldern. Charakterpilz magerer, saurer Föhren-/Fichtenstandorte.$g1$,$g1$mittel$g1$,$g1$An sauren, mageren Nadelwald-Standorten suchen - besonders dort, wo Heidelbeeren (Vaccinium) wachsen, ein verlässlicher Begleit-Indikator. In Bergnadelwäldern und an Moorrändern lohnend. Wegen erratischem Jahresverhalten gute Stellen über Jahre merken; in Massenjahren sehr ergiebig nach Herbstregen.$g1$,$g1$Web-Recherche Juni 2026: Wikipedia (Reifpilz), fundkorb.de, pilzmuseum.at, pilzvereinzug.ch (CH), tintling.com - Mykorrhiza Fichte/Kiefer (selten Buche), saure nährstoffarme Böden, Heidelbeer-Begleitung, August-Oktober, erratisches Massenvorkommen bestätigt.$g1$,true)
